/*
 Настройки бота управления умным домом.

 Заполнить вручную (искать «Заполнить»):
   bots.home.key          — токен бота из @BotFather
   access.profiles[].chatId — id семейного чата и личных сообщений
   access.users           — user_id тех, кому можно; узнать своё: команда /who

 Список устройств заполнять НЕ нужно: он строится обходом хаба.
 Что считать действием и кому что можно — actions.js и access.js.
*/
/* Собрано из src/02-settings/ — правки в этом файле потеряются при следующей сборке (tools/scenarios.py build). */
var TGActionsSettings = (function () {
// ───────────────────────────  actions.js  ───────────────────────────
/**
 * Правила: какие характеристики считать действиями и чем их рисовать.
 *
 * Правится руками, но редко: правил около десятка и они не зависят от того,
 * сколько у вас устройств. Сам список устройств не хранится нигде — он
 * строится обходом хаба (см. discovery.js).
 *
 * Отбор идёт БЕЛЫМ списком: в меню попадает только то, для чего есть правило
 * в ACTIONS или READONLY. Отдельного чёрного списка нет намеренно — он был,
 * но не отсекал ничего сверх белого списка и лишь создавал видимость фильтра.
 * Спрятать конкретное устройство можно через OVERRIDES с hide: true.
 *
 * Зависимостей нет.
 */
function TGActionsActions() {

    // kind:
    //   switch — две кнопки Вкл/Выкл
    //   range  — набор значений между getMinValue и getMaxValue
    //   choice — перечисление по labels
    // critical — действие требует допуска (см. access.js)
    var ACTIONS = {
        On: { kind: 'switch' },
        Active: { kind: 'switch', on: 1, off: 0, critical: true },
        Brightness: { kind: 'range', unit: '%', steps: [0, 25, 50, 75, 100] },
        ColorTemperature: { kind: 'range', points: 4 },
        TargetTemperature: { kind: 'range', unit: '°C', points: 5 },
        RotationSpeed: { kind: 'range', unit: '%', steps: [0, 20, 40, 60, 80, 100] },
        C_FanSpeed: { kind: 'range', points: 6 },
        TargetHeatingCoolingState: {
            kind: 'choice',
            labels: { '0': 'Выкл', '1': 'Тепло', '2': 'Холод', '3': 'Авто' }
        },
        SecuritySystemTargetState: {
            kind: 'choice',
            labels: { '0': 'Дома', '1': 'Ночь', '2': 'Охрана', '3': 'Снято' },
            critical: true
        }
    };

    // Показывать в сводке /status, но не давать кнопок.
    var READONLY = {
        CurrentTemperature: { unit: '°C' },
        CurrentRelativeHumidity: { unit: '%' },
        BatteryLevel: { unit: '%' },
        ContactSensorState: { labels: { '0': 'закрыто', '1': 'открыто' } },
        LeakDetected: { labels: { '0': 'сухо', '1': 'ПРОТЕЧКА' } },
        SmokeDetected: { labels: { '0': 'чисто', '1': 'ДЫМ' } },
        MotionDetected: { labels: { 'false': 'нет движения', 'true': 'движение' } }
    };

    // Точечные исключения по адресу 'aId,cId'. Разбирать значения из хаба
    // правилами по типу невозможно, когда дело в конкретном устройстве.
    var OVERRIDES = {
        '22,34': { hide: true },                        // «Самоочистка» кондиционера
        '19,19': { title: 'Сирена', critical: true },   // Датчик дыма → сирена
        '9,15': { title: 'Кран воды', critical: true },
        '25,15': { title: 'Водопроводный кран', critical: true }
    };

    return {
        ACTIONS: ACTIONS,
        READONLY: READONLY,
        OVERRIDES: OVERRIDES
    };
}

// ───────────────────────────  access.js  ───────────────────────────
/**
 * Кто и чем может управлять.
 *
 * Правится руками — это единственное место, где задаётся политика доступа.
 * Ссылаемся на комнаты по ИМЕНАМ, а не по числовым id: при перепаривании
 * устройства id в хабе меняется, имя комнаты — нет.
 *
 * Здесь лежит СТРУКТУРА политики, но не сами id: chatId и белый список людей
 * подставляются из неотслеживаемого local.js (см. local.example.js).
 * Репозиторий публичный, поэтому в отслеживаемых файлах только плейсхолдеры.
 *
 * Зависимости: local (может отсутствовать — тогда останутся плейсхолдеры).
 */
function TGActionsAccess(ns) {
    var local = ns && ns.local ? ns.local : null;

    // ─────────────────────────────  Профили чатов  ─────────────────────────
    // key       — короткий идентификатор, попадает в имена наборов кнопок
    // chatId    — id чата в Telegram; у групп он отрицательный
    // rooms     — какие комнаты видны в этом чате; '*' — все
    // allowCritical — можно ли в этом чате трогать критичное вообще
    var profiles = [
        {
            key: 'f',
            title: 'Семейный чат',
            chatId: 'Заполнить',
            rooms: ['Гостиная', 'Кухня', 'Детские комнаты', 'Кабинет', 'Улица'],
            allowCritical: false
        },
        {
            key: 'p',
            title: 'Личные сообщения',
            chatId: 'Заполнить',
            rooms: ['*'],
            allowCritical: true
        }
    ];

    // ────────────────────────────  Белый список людей  ─────────────────────
    // Ключ — user_id в Telegram (строкой). Узнать свой: команда /who.
    // critical: true — человеку разрешены критичные действия там, где их
    // разрешает профиль чата.
    var users = {
        'Заполнить': { name: 'Хозяин', critical: true }
    };

    // Автор не из списка: 'ignore' — молча не реагировать, 'deny' — ответить отказом.
    var strangerPolicy = 'deny';

    // Подстановка реальных значений из local.js. Профиль без chatId остаётся
    // с плейсхолдером и просто ни с одним чатом не совпадёт — это безопасный
    // отказ, а не тихое разрешение.
    if (local) {
        if (local.chats) {
            for (var i = 0; i < profiles.length; i++) {
                if (local.chats[profiles[i].key]) {
                    profiles[i].chatId = local.chats[profiles[i].key];
                }
            }
        }
        if (local.users) {
            users = local.users;
        }
    }

    function profileByChat(chatId) {
        var id = String(chatId);
        for (var i = 0; i < profiles.length; i++) {
            if (String(profiles[i].chatId) === id) {
                return profiles[i];
            }
        }
        return null;
    }

    function roomAllowed(profile, roomName) {
        if (!profile) {
            return false;
        }
        for (var i = 0; i < profile.rooms.length; i++) {
            if (profile.rooms[i] === '*' || profile.rooms[i] === roomName) {
                return true;
            }
        }
        return false;
    }

    /**
     * Можно ли выполнить действие. Возвращает {ok, reason}.
     *
     * Действие разрешено, когда комната входит в профиль чата И (действие
     * не критичное ИЛИ и профиль, и человек допущены к критичному).
     * Неизвестный человек не проходит никогда — так же, как чужой чат
     * не проходит на уровне движка.
     */
    function check(chatId, userId, item) {
        var profile = profileByChat(chatId);
        if (!profile) {
            return { ok: false, reason: 'Этот чат не настроен для управления домом' };
        }
        var user = users[String(userId)];
        if (!user) {
            return {
                ok: false,
                silent: strangerPolicy === 'ignore',
                reason: 'Вас нет в списке разрешённых. Ваш id: ' + userId
            };
        }
        if (!roomAllowed(profile, item.room)) {
            return { ok: false, reason: 'Комната «' + item.room + '» недоступна в этом чате' };
        }
        if (item.critical && !(profile.allowCritical && user.critical)) {
            return { ok: false, reason: 'Действие «' + item.title + '» здесь запрещено' };
        }
        return { ok: true, user: user, profile: profile };
    }

    return {
        profiles: profiles,
        users: users,
        profileByChat: profileByChat,
        roomAllowed: roomAllowed,
        check: check
    };
}

// ───────────────────────────  discovery.js  ───────────────────────────
/**
 * Обход хаба: строит список доступных действий и датчиков.
 *
 * Список устройств нигде не хранится — он каждый раз собирается из хаба.
 * Поэтому новое устройство появляется в меню после /refresh, переименование
 * подхватывается, а перепаривание не оставляет ссылок в никуда.
 *
 * Чтение из глобального сценария разрешено — проверено спайком в живом хабе
 * (см. JOURNAL.md, запись от 2026-08-28). Запись — нет, поэтому пишем только
 * из обработчиков кнопок, которые вызываются по цепочке от блочного сценария.
 *
 * Зависимости: actions.
 */
function TGActionsDiscovery(ns) {
    var rules = ns.actions;

    /**
     * UUID характеристики в хабе имеет вид 'aId.sId.cId'. Числовой пары
     * (aId, cId) нет в объектной модели сценариев, а Hub.setCharacteristicValue
     * принимает именно её — единственный вызов записи, проверенный на живом хабе.
     */
    function addressOf(characteristic) {
        var uuid;
        try {
            uuid = String(characteristic.getUUID());
        } catch (e) {
            return null;
        }
        var parts = uuid.split('.');
        if (parts.length < 3) {
            return null;
        }
        var aId = parseInt(parts[0], 10);
        var cId = parseInt(parts[2], 10);
        if (isNaN(aId) || isNaN(cId)) {
            return null;
        }
        return { aId: aId, cId: cId, key: aId + ',' + cId };
    }

    /** Набор значений для kind: 'range' — из правила либо из границ характеристики. */
    function rangeSteps(rule, characteristic) {
        if (rule.steps) {
            return rule.steps;
        }
        var min = characteristic.getMinValue();
        var max = characteristic.getMaxValue();
        if (min === null || max === null || min === undefined || max === undefined || max <= min) {
            return null;
        }
        var count = rule.points || 5;
        var out = [];
        var step = (max - min) / (count - 1);
        for (var i = 0; i < count; i++) {
            out.push(Math.round(min + step * i));
        }
        return out;
    }

    function describe(characteristic, accessory, service, roomName) {
        var type = String(characteristic.getType());
        var addr = addressOf(characteristic);
        if (!addr) {
            return null;
        }

        var override = rules.OVERRIDES[addr.key] || {};
        if (override.hide) {
            return null;
        }

        // Имя сервиса обычно осмысленнее имени характеристики: «Свет Даша»
        // против «Включен». Имя аксессуара берём, только если сервис безымянный.
        var title = override.title
            || String(service.getName() || accessory.getName() || type);

        var base = {
            key: addr.key,
            aId: addr.aId,
            cId: addr.cId,
            room: roomName,
            device: String(accessory.getName()),
            title: title,
            type: type
        };

        var rule = rules.ACTIONS[type];
        if (rule) {
            base.kind = rule.kind;
            base.critical = override.critical !== undefined ? override.critical : !!rule.critical;
            base.on = rule.on !== undefined ? rule.on : true;
            base.off = rule.off !== undefined ? rule.off : false;
            base.unit = rule.unit || '';
            base.labels = rule.labels || null;
            if (rule.kind === 'range') {
                base.steps = rangeSteps(rule, characteristic);
                if (!base.steps) {
                    return null;
                }
            }
            return base;
        }

        var ro = rules.READONLY[type];
        if (ro) {
            base.kind = 'readonly';
            base.unit = ro.unit || '';
            base.labels = ro.labels || null;
            return base;
        }

        return null;
    }

    /**
     * @returns {{actions: Array, sensors: Array, rooms: Array, errors: Array}}
     */
    function scan() {
        var actions = [];
        var sensors = [];
        var roomNames = [];
        var errors = [];

        var rooms;
        try {
            rooms = Hub.getRooms();
        } catch (e) {
            return { actions: [], sensors: [], rooms: [], errors: ['getRooms: ' + e] };
        }

        for (var r = 0; r < rooms.length; r++) {
            var roomName;
            try {
                roomName = String(rooms[r].getName());
            } catch (e) {
                errors.push('room ' + r + ': ' + e);
                continue;
            }
            var accs;
            try {
                accs = rooms[r].getAccessories();
            } catch (e) {
                errors.push(roomName + ': ' + e);
                continue;
            }
            var roomHasSomething = false;

            for (var a = 0; a < accs.length; a++) {
                var services;
                try {
                    services = accs[a].getServices(true);
                } catch (e) {
                    errors.push(roomName + '/' + a + ': ' + e);
                    continue;
                }
                for (var s = 0; s < services.length; s++) {
                    var chars;
                    try {
                        chars = services[s].getCharacteristics();
                    } catch (e) {
                        continue;
                    }
                    for (var c = 0; c < chars.length; c++) {
                        var item;
                        try {
                            item = describe(chars[c], accs[a], services[s], roomName);
                        } catch (e) {
                            continue;
                        }
                        if (!item) {
                            continue;
                        }
                        roomHasSomething = true;
                        if (item.kind === 'readonly') {
                            sensors.push(item);
                        } else {
                            actions.push(item);
                        }
                    }
                }
            }

            if (roomHasSomething) {
                roomNames.push(roomName);
            }
        }

        return { actions: actions, sensors: sensors, rooms: roomNames, errors: errors };
    }

    /** Текущее значение — читаем в момент показа, не кэшируем. */
    function readValue(item) {
        try {
            return Hub.getCharacteristicValue(item.aId, item.cId);
        } catch (e) {
            return null;
        }
    }

    /**
     * Запись. Проверять результат немедленным чтением НЕЛЬЗЯ: значение
     * доезжает асинхронно, и сразу после записи хаб отдаёт старое —
     * на этом уже был сделан неверный вывод (см. JOURNAL.md).
     */
    function writeValue(item, value) {
        Hub.setCharacteristicValue(item.aId, item.cId, value);
    }

    return {
        scan: scan,
        readValue: readValue,
        writeValue: writeValue,
        addressOf: addressOf
    };
}

// ───────────────────────────  menu.js  ───────────────────────────
/**
 * Меню: строится из результата обхода хаба, не пишется руками.
 *
 * Три уровня inline-кнопок: комната → устройство → действие. Inline, а не
 * reply-клавиатура: в группе бот по умолчанию не видит обычный текст
 * (Privacy Mode), а callback_query приходит всегда.
 *
 * Наборы кнопок строятся отдельно для каждого профиля чата — так в семейном
 * чате физически нет кнопок, которых там быть не должно, и фильтровать при
 * отправке не требуется.
 *
 * Имена наборов короткие намеренно: они уезжают в callback_data, у которого
 * лимит 64 байта, а кириллица там стоит два байта на символ.
 *
 * Зависимости: access, discovery.
 */
function TGActionsMenu(ns) {
    var access = ns.access;
    var discovery = ns.discovery;

    var BACK = '‹ Назад';

    function send(cq, text) {
        global.TGActions.sendSimpleMessage(cq.botName, String(cq.message.chat.id), text);
    }

    function open(cq, setName, text) {
        global.TGActions.sendInteractiveMessage(
            cq.botName, String(cq.message.chat.id), setName, text, { notify: false });
    }

    function valueLabel(item, value) {
        if (item.labels) {
            var byLabel = item.labels[String(value)];
            if (byLabel) {
                return byLabel;
            }
        }
        if (item.kind === 'switch') {
            return value === item.on ? 'включено' : 'выключено';
        }
        if (value === null || value === undefined) {
            return '—';
        }
        return String(value) + (item.unit ? ' ' + item.unit : '');
    }

    /** Кнопки конкретного действия: Вкл/Выкл, набор значений либо перечисление. */
    function actionButtons(item, backSet) {
        var row = [];
        var i;

        if (item.kind === 'switch') {
            row.push(valueButton(item, item.on, 'Включить'));
            row.push(valueButton(item, item.off, 'Выключить'));
        } else if (item.kind === 'range') {
            for (i = 0; i < item.steps.length; i++) {
                row.push(valueButton(item, item.steps[i],
                    String(item.steps[i]) + (item.unit ? ' ' + item.unit : '')));
            }
        } else if (item.kind === 'choice') {
            for (var k in item.labels) {
                if (item.labels.hasOwnProperty(k)) {
                    row.push(valueButton(item, parseInt(k, 10), item.labels[k]));
                }
            }
        }

        var rows = [];
        // По три кнопки в ряд: длинные ряды в Telegram сжимаются в нечитаемое.
        for (i = 0; i < row.length; i += 3) {
            rows.push(row.slice(i, i + 3));
        }
        rows.push([navButton(backSet, BACK)]);
        return rows;
    }

    function valueButton(item, value, label) {
        return {
            text: label,
            handler: function (cq) {
                var verdict = access.check(cq.message.chat.id, cq.userId, item);
                if (!verdict.ok) {
                    if (!verdict.silent) {
                        send(cq, '⛔ ' + verdict.reason);
                    }
                    return;
                }
                try {
                    discovery.writeValue(item, value);
                } catch (e) {
                    send(cq, '⚠️ Не удалось: ' + e);
                    return;
                }
                // Подтверждаем намерение, а не результат: значение в хабе
                // доезжает асинхронно, и немедленное чтение врёт.
                send(cq, '✅ ' + item.room + ' · ' + item.title + ' → ' + label);
            }
        };
    }

    function navButton(setName, label) {
        return {
            text: label,
            handler: function (cq) {
                open(cq, setName, label === BACK ? 'Назад' : label);
            }
        };
    }

    /**
     * Собирает все наборы кнопок для всех профилей.
     * @returns {{buttonSets: Object, homeOf: Object, index: Object}}
     */
    function build(inventory) {
        var buttonSets = {};
        var homeOf = {};
        var index = { rooms: 0, devices: 0, actions: 0 };

        for (var p = 0; p < access.profiles.length; p++) {
            var profile = access.profiles[p];
            var homeRows = [];

            for (var r = 0; r < inventory.rooms.length; r++) {
                var roomName = inventory.rooms[r];
                if (!access.roomAllowed(profile, roomName)) {
                    continue;
                }

                var devices = groupByDevice(inventory.actions, roomName, profile);
                if (!devices.order.length) {
                    continue;
                }

                var roomSet = profile.key + 'r' + r;
                var deviceRows = [];

                for (var d = 0; d < devices.order.length; d++) {
                    var deviceName = devices.order[d];
                    var items = devices.map[deviceName];
                    var deviceSet = profile.key + 'd' + r + '_' + d;
                    var actionRows = [];

                    for (var i = 0; i < items.length; i++) {
                        var actionSet = profile.key + 'a' + r + '_' + d + '_' + i;
                        buttonSets[actionSet] = actionButtons(items[i], deviceSet);
                        actionRows.push([navButton(actionSet, items[i].title)]);
                        index.actions++;
                    }
                    actionRows.push([navButton(roomSet, BACK)]);
                    buttonSets[deviceSet] = actionRows;
                    deviceRows.push([navButton(deviceSet, deviceName)]);
                    index.devices++;
                }

                deviceRows.push([navButton(profile.key + 'h', BACK)]);
                buttonSets[roomSet] = deviceRows;
                homeRows.push([navButton(roomSet, roomName)]);
                index.rooms++;
            }

            buttonSets[profile.key + 'h'] = homeRows.length
                ? homeRows
                : [[{ text: 'Нет доступных устройств', handler: function () {} }]];
            homeOf[String(profile.chatId)] = profile.key + 'h';
        }

        return { buttonSets: buttonSets, homeOf: homeOf, index: index };
    }

    /** Действия комнаты, сгруппированные по устройству, с сохранением порядка. */
    function groupByDevice(actions, roomName, profile) {
        var map = {};
        var order = [];
        for (var i = 0; i < actions.length; i++) {
            var item = actions[i];
            if (item.room !== roomName) {
                continue;
            }
            // Критичное не показываем там, где профиль его запрещает: кнопки,
            // которой нет, нельзя нажать по ошибке. Проверка в обработчике
            // при этом остаётся — она защищает от чужого человека в своём чате.
            if (item.critical && !profile.allowCritical) {
                continue;
            }
            if (!map[item.device]) {
                map[item.device] = [];
                order.push(item.device);
            }
            map[item.device].push(item);
        }
        return { map: map, order: order };
    }

    return {
        build: build,
        valueLabel: valueLabel
    };
}

// ───────────────────────────  commands.js  ───────────────────────────
/**
 * Команды бота.
 *
 * Зависимости: access, discovery, menu, state.
 */
function TGActionsCommands(ns) {
    var access = ns.access;
    var discovery = ns.discovery;
    var menu = ns.menu;
    var state = ns.menuState;

    function reply(ctx, text) {
        global.TGActions.sendSimpleMessage(ctx.botName, String(ctx.chatId), text);
    }

    /** Общий вход: чат настроен и человек известен. */
    function gate(ctx) {
        var profile = access.profileByChat(ctx.chatId);
        if (!profile) {
            reply(ctx, '⛔ Этот чат не настроен для управления домом.\nchat_id: ' + ctx.chatId);
            return null;
        }
        if (!access.users[String(ctx.userId)]) {
            reply(ctx, '⛔ Вас нет в списке разрешённых.\nВаш id: ' + ctx.userId);
            return null;
        }
        return profile;
    }

    var commands = {
        home: {
            description: 'Меню управления домом',
            handler: function (ctx) {
                var profile = gate(ctx);
                if (!profile) {
                    return;
                }
                global.TGActions.sendInteractiveMessage(
                    ctx.botName, String(ctx.chatId), profile.key + 'h',
                    'Дом. Выберите комнату:', { notify: false });
            }
        },

        status: {
            description: 'Показания датчиков',
            handler: function (ctx) {
                var profile = gate(ctx);
                if (!profile) {
                    return;
                }
                var lines = [];
                var lastRoom = null;
                var sensors = state.inventory.sensors;
                for (var i = 0; i < sensors.length; i++) {
                    var s = sensors[i];
                    if (!access.roomAllowed(profile, s.room)) {
                        continue;
                    }
                    if (s.room !== lastRoom) {
                        lines.push('');
                        lines.push('*' + s.room + '*');
                        lastRoom = s.room;
                    }
                    lines.push(s.title + ': ' + menu.valueLabel(s, discovery.readValue(s)));
                }
                reply(ctx, lines.length ? lines.join('\n') : 'Датчиков в доступных комнатах нет');
            }
        },

        who: {
            description: 'Кто я для бота',
            handler: function (ctx) {
                var profile = access.profileByChat(ctx.chatId);
                var user = access.users[String(ctx.userId)];
                reply(ctx, [
                    'Ваш user_id: ' + ctx.userId,
                    'Имя: ' + (ctx.userName || '—'),
                    'chat_id: ' + ctx.chatId,
                    'Профиль чата: ' + (profile ? profile.title : 'не настроен'),
                    'В белом списке: ' + (user ? 'да' : 'нет'),
                    'Критичные действия: ' + (user && user.critical && profile && profile.allowCritical
                        ? 'разрешены' : 'запрещены')
                ].join('\n'));
            }
        },

        refresh: {
            description: 'Перечитать устройства из хаба',
            handler: function (ctx) {
                if (!gate(ctx)) {
                    return;
                }
                var result = state.refresh();
                reply(ctx, [
                    'Обход хаба выполнен.',
                    'Комнат: ' + result.inventory.rooms.length,
                    'Действий: ' + result.index.actions,
                    'Датчиков: ' + result.inventory.sensors.length,
                    result.inventory.errors.length
                        ? 'Ошибок обхода: ' + result.inventory.errors.length
                        : 'Ошибок нет'
                ].join('\n'));
            }
        },

        help: {
            description: 'Список команд',
            handler: function (ctx) {
                var lines = [];
                for (var name in commands) {
                    if (commands.hasOwnProperty(name)) {
                        lines.push('/' + name + ' — ' + commands[name].description);
                    }
                }
                reply(ctx, lines.join('\n'));
            }
        }
    };

    return commands;
}

